import{_ as o,C as r,o as s,c as i,a6 as t,E as n}from"./chunks/framework.CCKCzdWs.js";const h="/screenshots/failure-headline.png",w=JSON.parse('{"title":"Your first failure, explained","description":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the next step, the cluster and the evidence.","frontmatter":{"title":"Your first failure, explained","description":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the next step, the cluster and the evidence.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/first-failure.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/first-failure.html"}],["meta",{"property":"og:title","content":"Your first failure, explained | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Read one failing test in the dashboard from top to bottom: the headline, the likely cause, the next step, the cluster and the evidence."}]]},"headers":[],"relativePath":"guide/first-failure.md","filePath":"guide/first-failure.md","lastUpdated":1794867328000}'),l={name:"guide/first-failure.md"};function d(c,e,u,f,p,m){const a=r("DemoExamples");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="your-first-failure-explained" tabindex="-1">Your first failure, explained <a class="header-anchor" href="#your-first-failure-explained" aria-label="Permalink to &quot;Your first failure, explained&quot;">​</a></h1><p>You&#39;ve landed your first run (<a href="./getting-started.html">Getting started</a>) and one test is red. This page walks through reading it. Piwi lays a failing execution out <strong>diagnosis-first</strong>, in one column read top to bottom: <em>what</em> broke, <em>why</em>, <em>what to do next</em>, then the evidence.</p><p>Open the failing test from the run page (click its row) to reach its <strong>execution page</strong>.</p><figure><img src="'+h+'" alt="A failing execution&#39;s situation block: the identity line, the headline, the line saying since when it fails, Most likely with its strength, the Next step with the patch to apply, and the Cluster line"><figcaption>The situation block: what broke, since when, why, what to do next, and the cluster it belongs to.</figcaption></figure><p>The top of the page is one <strong>situation block</strong>. Above its heading, a small <strong>identity</strong> line carries the status, the test (<code>tests/checkout/checkout.spec.ts:9 › Checkout › should complete checkout with credit card</code>), marks such as <code>@fixme</code> or <code>@slow</code>, and whether it is <a href="/features/flaky-tests.html#quarantine-with-a-way-out">quarantined</a>. The lines below it are the rest of this page, in order.</p><h2 id="_1-the-headline-what-broke" tabindex="-1">1. The headline: what broke <a class="header-anchor" href="#_1-the-headline-what-broke" aria-label="Permalink to &quot;1. The headline: what broke&quot;">​</a></h2><p>The heading is a plain-English sentence built from the Playwright error, before you read a word of the raw error itself:</p><blockquote><p><code>Test timed out after 30 s while clicking getByRole(&#39;button&#39;, { name: &#39;Pay&#39; })</code></p></blockquote><p>It is read from the action or matcher, the locator, the expected and received values and the timeout; an unknown error shape falls back to the error&#39;s first line. A failure in a hook or fixture says where it happened (<code>In beforeEach: …</code>), and an <code>expect</code> you gave a message leads with it (<code>&quot;cart shows the item&quot; failed: …</code>). The verbatim error is one click away under <strong>Raw error</strong>: Piwi never rewrites it, it only leads with a readable summary. The same headline names the test on the run page, in <a href="/features/notifications.html">alerts</a>, in the <a href="/features/pr-feedback.html">pull-request comment</a>, in the MCP tools and in your terminal.</p><p>A smaller line under the headline says since when it fails, on which commit and by whom, and whether it <strong>still fails</strong>:</p><blockquote><p><em>New regression since a1b2c3d by Alice Chen, 1 day ago · Not the latest Chromium execution: failed again in run #1 and run #2, 51 minutes ago · Open the latest</em></p></blockquote><p><em>Latest execution of this test</em> means nothing ran it since; otherwise the line says what the newer runs did (failed again, with another error, or passed) and <strong>Open the latest</strong> goes to the newest execution. Only the same Playwright project counts, and the line names it when another project ran later: a Firefox pass does not clear a Chromium failure. An exceptional case (a new regression, a newly flaky test, an infrastructure failure) leads the line. A test that passed on retry reads <em>Passed on retry</em> in its status and leads with its failed attempt&#39;s error, and the line says which attempt failed (<em>Failed on attempt 1, passed on attempt 2</em>), with a link to it.</p><h2 id="_2-most-likely-why" tabindex="-1">2. Most likely: why <a class="header-anchor" href="#_2-most-likely-why" aria-label="Permalink to &quot;2. Most likely: why&quot;">​</a></h2><p>Under the headline, the <strong>Most likely</strong> line gives one explanation. It is built from <strong><a href="/features/evidence.html#clues">clues</a></strong>: deterministic, rule-based findings correlated from the evidence, with <em>no model involved</em>. When the clues match a known pattern (some patterns need only one clue), the line is a <a href="./concepts.html#story">story</a>, one sentence that chains them:</p><blockquote><p><em>The button &quot;Pay&quot; stayed disabled because POST /api/checkout/quote was still in flight (28.4 s); the console said so 7.8 s before the click gave up.</em></p></blockquote><p>A strong or medium story leads; otherwise the cluster&#39;s <a href="/features/ai-diagnosis.html">AI diagnosis</a> may, by one rule on this page and the cluster page (<a href="/reference/clues.html#most-likely">which one leads</a>). The line carries a strength (<em>Strong</em>, <em>Medium</em> or <em>Weak</em>, or the diagnosis&#39;s confidence) and how many clues <strong>agree</strong>; <strong>All clues</strong> lists every clue, each with a <strong>citation</strong>: click it and the page jumps to the proof. With no clue and no diagnosis, the line is absent.</p><p>A test that did not run gets its reason here instead: the test that blocked it, or where the run stopped (<em>The run reached its maximum number of failures (3 failed) and stopped before this test started</em>), with a meta line when Playwright reported it.</p><h2 id="_3-next-what-to-do" tabindex="-1">3. Next: what to do <a class="header-anchor" href="#_3-next-what-to-do" aria-label="Permalink to &quot;3. Next: what to do&quot;">​</a></h2><p>The <strong>Next</strong> line names the one thing to do, chosen for you rather than offered as a menu: apply the diagnosed patch, replace the <a href="/features/locator-healing.html">broken locator</a>, reproduce it, re-run in CI, mark the cluster resolved, or, for a test that did not run, open what blocked it. A code change shows on the line itself, with where it comes from and a button that copies it (<strong>Copy apply command</strong> or <strong>Copy locator</strong>); the <strong>···</strong> menu copies the command that re-runs this test. How the step is chosen and every action it offers: <a href="/features/fix-plans.html#the-next-step">The next step</a>.</p><h2 id="_4-the-cluster-who-else-and-the-ticket" tabindex="-1">4. The cluster: who else, and the ticket <a class="header-anchor" href="#_4-the-cluster-who-else-and-the-ticket" aria-label="Permalink to &quot;4. The cluster: who else, and the ticket&quot;">​</a></h2><p>The <strong>Cluster</strong> line names the <a href="/features/failure-clusters.html">failure cluster</a> the failure joins and how many other tests of the run share it, with its triage status, whether an earlier fix did not hold, and who owns the test. It ends with the cluster&#39;s <a href="/features/issue-tracking.html">issue</a> and its status, or offers to create or link one.</p><p>With <a href="/features/server-coverage.html">coverage</a>, a <strong>What changed</strong> line counts the changed lines the test ran and names the first of its <a href="/guide/concepts.html#suspect-lines">suspect lines</a>.</p><p>The block closes on a <strong>facts</strong> line, one size smaller: the failing file and line (open it in your IDE), browser and viewport, duration against its average, the attempts, the branch, and the CI build. A <strong>Details</strong> popover holds the rest, and <strong>Raw error</strong> shows the verbatim error with a <strong>Copy failure</strong> action.</p><h2 id="_5-the-evidence-see-it" tabindex="-1">5. The evidence: see it <a class="header-anchor" href="#_5-the-evidence-see-it" aria-label="Permalink to &quot;5. The evidence: see it&quot;">​</a></h2><p>One <strong>evidence card</strong> with tabs holds everything captured, opening on the tab that best shows the failure (<a href="/features/evidence.html#one-execution-diagnosis-first">which one</a>); a click on any citation switches tabs for you. The one to know first is <strong>Timeline</strong>: it places the test&#39;s steps, console entries, network requests and backend logs on a single clock and marks the <strong>moment of failure</strong>, so &quot;console (1) / network (3)&quot; becomes <em>what the app was doing when the test gave up</em>. <strong>Screen</strong> holds the failure screenshot, the visual diff against the <a href="/features/run-changes.html#one-execution-s-baseline">last green run</a>, and the failure-time page state; <strong>Source</strong> shows the test source as a real call stack, so a failure inside a helper shows the helper. Each tab is described on <a href="/features/evidence.html">Failure evidence</a>.</p><div class="tip custom-block"><p class="custom-block-title">Most of this needs one file</p><p>The error, trace, headline and clustering work with the reporter alone, and an uploaded trace recovers the console, network and failure-time snapshot. Web Vitals, page state and locator healing come from the <a href="./capture-fixtures.html">capture fixtures</a>, one file in your test setup. A tab that needs them and never received any data is left out, and until you decide on the fixtures one footer line names what they would add.</p></div><h2 id="_6-more-ways-to-fix" tabindex="-1">6. More ways to fix <a class="header-anchor" href="#_6-more-ways-to-fix" aria-label="Permalink to &quot;6. More ways to fix&quot;">​</a></h2><p>Below the evidence, <strong><a href="/features/fix-plans.html#more-ways-to-fix">More ways to fix</a></strong> is the folded toolbox of every <em>other</em> way to fix, verify or reproduce, with the section <strong>Next</strong> points at already open: a <a href="/features/locator-healing.html">replacement locator</a>, the <a href="/features/ai-diagnosis.html">AI diagnosis</a> and its validated patch, verify, reproduce and bisect, fixed before, the tests it blocked.</p><p>Below the toolbox, a <strong>history</strong> strip shows this test&#39;s recent executions and how long it has been failing.</p><h2 id="you-re-not-reading-it-alone" tabindex="-1">You&#39;re not reading it alone <a class="header-anchor" href="#you-re-not-reading-it-alone" aria-label="Permalink to &quot;You&#39;re not reading it alone&quot;">​</a></h2><p>This execution is one member of a <strong><a href="/features/failure-clusters.html">failure cluster</a></strong>: Piwi groups every test that failed for the same reason, so forty red tests become three problems you triage once. Once a later run passes every test it covers, the cluster records <a href="/features/failure-clusters.html#did-the-fix-work">whether the fix held</a>.</p><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',32)),n(a),e[1]||(e[1]=t('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/evidence.html">Failure evidence</a>: each evidence tab, attempts, the page diff and the trace views</li><li><a href="/reference/clues.html">Clue rules</a>: every rule behind the <strong>Most likely</strong> line</li><li><a href="/features/failure-clusters.html">Failure clusters</a>: triaging failures as groups</li><li><a href="./capture-fixtures.html">Capture fixtures</a>: the one file that unlocks the richer evidence</li><li><a href="./core-concepts.html">Core concepts</a>: run, execution, cluster, fingerprint, baseline</li></ul>',2))])}const y=o(l,[["render",d]]);export{w as __pageData,y as default};
